const test = require('node:test');
const assert = require('node:assert/strict');
const fs = require('node:fs/promises');
const path = require('node:path');
const os = require('node:os');
const { gzipSync } = require('node:zlib');
const { createRuntime, load, CORE_FILES } = require('./helpers.cjs');

// V2.5.5.9 bypass export: fixtures are real client-generated bypass objects (V2.5.5.7) with injected
// satellite shadows (V2.5.5.8), stored the way replay-snapshot.js stores them.
const LOCATION = { latitude: 22.5431, longitude: 114.0579 };
const SOLAR = { sunset: new Date('2026-09-09T10:30:00.000Z'), sunsetAzimuthDeg: 278 };
const NOW = Date.parse('2026-09-09T04:13:00.000Z');
const SHADOW_FILES = ['js/config.js', 'js/model_config.js', 'js/network.js', 'js/corridor.js', 'js/satellite_colormap.js', 'js/satellite_shadow.js'];
const DOMAIN = "<Domains><DimensionDomain><ows:Identifier>time</ows:Identifier><Domain>2026-10-28T01:00:00Z/2026-10-28T02:30:00Z/PT10M,2026-10-28T02:50:00Z/2026-10-28T06:30:00Z/PT10M</Domain><Size>2</Size></DimensionDomain></Domains>";
const plain = value => JSON.parse(JSON.stringify(value));

function omFetch() {
  return async url => {
    const u = new URL(url), variables = u.searchParams.get('hourly').split(','), count = u.searchParams.get('latitude').split(',').length;
    const time = Array.from({ length: 24 }, (_, h) => `2026-09-09T${String(h).padStart(2, '0')}:00`);
    const unit = n => n === 'dew_point_2m' ? '°C' : (n === 'boundary_layer_height' || n.startsWith('geopotential_height_')) ? 'm' : '%';
    const value = n => n === 'dew_point_2m' ? 21.5 : n === 'boundary_layer_height' ? 640 : n.startsWith('geopotential_height_') ? 5800 : 35;
    const one = () => ({ utc_offset_seconds: 28800, timezone: 'Asia/Shanghai', elevation: 12,
      hourly_units: Object.fromEntries([['time', 'iso8601'], ...variables.map(n => [n, unit(n)])]),
      hourly: Object.fromEntries([['time', time], ...variables.map(n => [n, time.map(() => value(n))])]) });
    const body = Array.from({ length: count }, one);
    return new Response(JSON.stringify(count === 1 ? body[0] : body), { status: 200, headers: { 'content-type': 'application/json' } });
  };
}
let fixturePromise;
function fixtures() {
  fixturePromise ||= (async () => {
    const base = plain(await load(createRuntime({ fetch: omFetch() }), [...CORE_FILES, 'js/bypass_capture.js']).bypassCapture
      .capture({ location: LOCATION, solar: SOLAR, nowUtcMs: NOW }));
    const SS = load(createRuntime(), SHADOW_FILES), entries = SS.satelliteColormap.entries;
    const colour = fn => entries.find(e => fn(e[3]));
    const shadow = async rgb => plain(await SS.satelliteShadow.capture({ location: { latitude: 31.23, longitude: 121.47 }, solar: { sunsetAzimuthDeg: 255 },
      nowUtcMs: Date.parse('2026-10-28T06:59:00Z'), fetchText: async () => DOMAIN,
      loadTile: async url => { const a = new Uint8ClampedArray(256 * 256 * 4); for (let i = 0; i < a.length; i += 4) { a[i] = rgb[0]; a[i + 1] = rgb[1]; a[i + 2] = rgb[2]; a[i + 3] = 255; }
        return { ok: true, timeActual: url.match(/default\/([^/]+)\//)[1], rgba: a }; } }));
    return { base, cold: await shadow(colour(v => v <= -40)), warm: await shadow(colour(v => v >= 20)) };
  })();
  return fixturePromise;
}

let modulePromise;
const api = () => modulePromise ||= Promise.all([import('../tools/bypass/export-bypass.mjs'), import('../tools/bypass/validate-bypass.mjs'),
  import('../tools/bypass/lib/core.mjs'), import('../tools/bypass/lib/source.mjs'), import('../server/replay-schema.js'),
  import('../tools/dataset/lib/csv.mjs'), import('../tools/dataset/dataset-schema.mjs'), import('../tools/dataset/lib/common.mjs')])
  .then(([exp, val, core, source, replay, csv, schema, common]) => ({ exp, val, core, source, canonicalJson: replay.canonicalJson, csv, schema, common }));

function snapshot(id, extra = {}) {
  return { id, event_id: 'evt_v1_test_2026-10-29', event_date_local: '2026-10-29', city: '深圳', latitude: LOCATION.latitude, longitude: LOCATION.longitude,
    sunset_time_utc: SOLAR.sunset.toISOString(), prediction_time_utc: new Date(NOW).toISOString(), snapshot_source: 'github_schedule',
    scheduled_slot: '1613', app_version: '2.5.5.8', model_version: '2.5.5.4', replay_status: 'READY',
    replay_object_key: `replay/v1/2026/10/29/evt/${id}.json.gz`, replay_sha256: 'a'.repeat(64),
    replay_saved_at_utc: '2026-10-29T08:14:00.000Z', submitted_at_epoch: Date.parse('2026-10-29T08:14:00Z'), ...extra };
}

async function setup(t) {
  const m = await api(), f = await fixtures(), dir = await fs.mkdtemp(path.join(os.tmpdir(), 'sunset-bypass-'));
  t.after(() => fs.rm(dir, { recursive: true, force: true }));
  const stored = (row, mutate = () => {}) => {
    const payload = structuredClone(f.base); mutate(payload); payload.snapshot_id = row.id;
    return gzipSync(Buffer.from(m.canonicalJson(payload)));
  };
  const rows = [
    snapshot('snap_a', { submitted_at_epoch: 1 }), snapshot('snap_b', { submitted_at_epoch: 2 }), snapshot('snap_c', { submitted_at_epoch: 3 }),
    snapshot('snap_d', { submitted_at_epoch: 4 }), snapshot('snap_e', { submitted_at_epoch: 5, snapshot_source: 'user_feedback', scheduled_slot: null }),
    snapshot('snap_f', { submitted_at_epoch: 6, app_version: '2.5.5.6' }), snapshot('snap_g', { submitted_at_epoch: 7, snapshot_source: 'github_manual', app_version: '2.5.5.7' }),
    snapshot('snap_h', { submitted_at_epoch: 8 })
  ];
  const objects = new Map([
    ['snap_a', stored(rows[0], p => { p.satellite_shadow = f.cold; })],
    ['snap_b', stored(rows[1], p => { p.satellite_shadow = f.warm; })],
    ['snap_d', stored(rows[3], p => { p.latitude += 0.01; })],
    ['snap_g', stored(rows[6], p => { p.bypass_schema_version = 1; })]
  ].map(([id, bytes]) => [m.core.objectKeyFor(rows.find(r => r.id === id)), bytes]));
  const calls = [];
  const source = {
    async query(sql) {
      if (sql.includes('strftime')) return [{ cutoff_epoch: Date.parse('2026-10-29T12:00:00Z') }];
      assert.doesNotMatch(sql, /sunset_observations/);
      return sql.includes('AND (submitted_at_epoch >') ? [] : rows;
    },
    async getObject(key) {
      calls.push(key);
      if (key.includes('snap_h')) throw Object.assign(new Error('DOWNLOAD_FAILED'), { code: 'DOWNLOAD_FAILED' });
      return objects.has(key) ? { status: 'FOUND', bytes: objects.get(key) } : { status: 'MISSING' };
    }
  };
  const options = m.exp.parseArgs(['--output', dir, '--from', '2026-10-28', '--to', '2026-10-29', '--quiet'], Date.parse('2026-10-29T12:00:00Z'));
  const run = (extra = {}) => m.exp.exportBypass({ ...options, ...extra }, { source, createdAt: 0, commit: null });
  return { m, dir, rows, calls, run };
}

test('Arguments, selection SQL and the EXPECTED rule (automatic captures on 2.5.5.7+ only)', async () => {
  const { exp, core } = await api();
  const o = exp.parseArgs([], Date.parse('2026-10-29T17:00:00Z'));
  assert.deepEqual([o.selection.event_date_from, o.selection.event_date_to, o.maxMinutes, o.refresh], ['2026-10-28', '2026-10-30', 50, false]);
  assert.throws(() => exp.parseArgs(['--from', '2026-10-30', '--to', '2026-10-29']), /INVALID_DATE_RANGE/);
  assert.throws(() => exp.parseArgs(['--snapshot-source', 'cron']), /INVALID_FILTER/);
  assert.throws(() => exp.parseArgs(['--include-comments']), /INVALID_ARGUMENTS/);
  const sql = exp.snapshotCondition({ event_date_from: '2026-10-28', event_date_to: '2026-10-29', cities: ['深圳'], snapshot_sources: null, scheduled_slots: ['1613'] }, 99);
  assert.match(sql, /event_date_local >= '2026-10-28'/); assert.match(sql, /city COLLATE BINARY IN \('深圳'\)/); assert.match(sql, /submitted_at_epoch <= 99/);
  assert.deepEqual(['2.5.5.7', '2.5.5.10', '2.5.5.6', '2.5.6', 'x'].map(v => core.versionAtLeast(v, '2.5.5.7')), [true, true, false, true, false]);
  assert.equal(core.expectation({ snapshot_source: 'github_schedule', app_version: '2.5.5.8' }), 'EXPECTED');
  assert.equal(core.expectation({ snapshot_source: 'user_feedback', app_version: '2.5.5.8' }), 'NOT_EXPECTED');
  assert.equal(core.expectation({ snapshot_source: 'github_manual', app_version: '2.5.5.6' }), 'NOT_EXPECTED');
});

test('R2 reads: an absent key is MISSING without retry; transient failures retry three times; other failures stop', async t => {
  const { source } = await api(), dir = await fs.mkdtemp(path.join(os.tmpdir(), 'sunset-bypass-src-'));
  t.after(() => fs.rm(dir, { recursive: true, force: true }));
  assert.deepEqual(['The specified key does not exist. [code: 10007]', 'ETIMEDOUT', 'Authentication error'].map(source.classifyR2Failure), ['MISSING', 'TRANSIENT', 'FAILED']);
  const make = outcomes => { let i = 0; const calls = [];
    return { calls, src: source.createBypassSource({ bucket: 'b', config: null }, dir, { delay: async () => {},
      run: async invocation => { calls.push(invocation); const o = outcomes[Math.min(i++, outcomes.length - 1)];
        if (o === 'ok') { await fs.writeFile(invocation.args[invocation.args.indexOf('--file') + 1], 'gz'); return { error: null, diagnostic: '' }; }
        return { error: new Error('x'), diagnostic: o }; } }) }; };
  let s = make(['The specified key does not exist']); assert.deepEqual(await s.src.getObject('k'), { status: 'MISSING' }); assert.equal(s.calls.length, 1);
  s = make(['ECONNRESET', 'ok']); assert.equal((await s.src.getObject('k')).bytes.toString(), 'gz'); assert.equal(s.calls.length, 2);
  s = make(['ETIMEDOUT']); await assert.rejects(s.src.getObject('k'), /DOWNLOAD_FAILED/); assert.equal(s.calls.length, 4);
  s = make(['Authentication error']); await assert.rejects(s.src.getObject('k'), /DOWNLOAD_FAILED/); assert.equal(s.calls.length, 1);
  assert.ok(s.calls[0].args.includes('b/k') && s.calls[0].args.includes('--remote'));
});

test('Export classifies every Snapshot, verifies binding, reports label-free quality and caches objects', async t => {
  const { m, dir, calls, run } = await setup(t);
  const result = await run();
  assert.equal(result.status, 'EXPORTED', JSON.stringify(result));
  assert.deepEqual(result.counts, { snapshots: 8, expected: 6, valid: 3, missing: 1, invalid: 1, download_failed: 1 });
  const index = m.csv.readCsv(m.core.INDEX_FIELDS, await fs.readFile(path.join(result.directory, 'index.csv')));
  const by = Object.fromEntries(index.map(r => [r.snapshot_id, r]));
  assert.deepEqual(['a', 'b', 'c', 'd', 'e', 'f', 'g', 'h'].map(x => by['snap_' + x].object_status),
    ['VALID', 'VALID', 'MISSING', 'INVALID', 'NOT_CHECKED', 'NOT_CHECKED', 'VALID', 'DOWNLOAD_FAILED']);
  assert.equal(by.snap_d.error_code, 'BYPASS_BINDING_MISMATCH');
  assert.deepEqual([by.snap_a.bypass_schema_version, by.snap_a.shadow_status, by.snap_g.bypass_schema_version, by.snap_g.shadow_status], [2, 'OK', 1, null]);
  assert.equal(by.snap_a.bypass_object_key, 'replay/v1/2026/10/29/evt/snap_a.bypass.json.gz');
  assert.ok(!calls.some(k => k.includes('snap_e') || k.includes('snap_f')), 'NOT_EXPECTED Snapshots are not downloaded');
  const quality = JSON.parse(await fs.readFile(path.join(result.directory, 'reports/quality.json'), 'utf8'));
  assert.equal(quality.status, 'WARN');
  assert.deepEqual(quality.warnings.map(w => w.code), ['EXPECTED_OBJECTS_NOT_VALID']);
  assert.deepEqual([quality.coverage.expected, quality.coverage.valid_ratio, quality.requests.A.ok_ratio], [6, 0.5, 1]);
  assert.deepEqual(quality.satellite_shadow.status, { OK: 2 });
  assert.deepEqual([quality.satellite_shadow.cold_cloud_cases.length, quality.satellite_shadow.worldview_candidates.cloudy[0].snapshot_id,
    quality.satellite_shadow.worldview_candidates.clear[0].snapshot_id], [1, 'snap_a', 'snap_b']);
  assert.equal(quality.satellite_shadow.spearman_frac_cloud_vs_nwp_mid_high, null, 'fewer than 10 pairs');
  assert.match(await fs.readFile(path.join(result.directory, 'reports/quality.md'), 'utf8'), /旁路对象质量周报[\s\S]*Worldview/);
  const first = calls.length;
  const again = await run();
  assert.deepEqual([again.status, again.bypass_dataset_id, again.cache_hits, again.downloads], ['DEDUPLICATED', result.bypass_dataset_id, 3, 0]);
  assert.equal(calls.length - first, 3, 'only MISSING, INVALID and failed objects are fetched again');
  const refreshed = await run({ refresh: true });
  assert.deepEqual([refreshed.status, refreshed.downloads], ['DEDUPLICATED', 3]);
  assert.deepEqual(await fs.readdir(path.join(dir, 'bypass/staging')), []);
});

test('Validation re-verifies objects, detects tampering and reports the join with a Raw package', async t => {
  const { m, dir, run } = await setup(t), result = await run();
  const checked = await m.val.validateBypass({ dataset: result.directory, raw: null });
  assert.deepEqual([checked.status, checked.verified_objects, checked.quality_status], ['PASS', 3, 'WARN']);
  const raw = path.join(dir, 'raw_pkg'); await fs.mkdir(path.join(raw, 'raw'), { recursive: true });
  await fs.writeFile(path.join(raw, 'manifest.json'), JSON.stringify({ descriptor: { selection: { include_comments: false } } }));
  const fields = m.schema.datasetSchema(false).tables.replay_index;
  const rawRow = (id, sha) => ({ snapshot_id: id, event_id: 'evt_v1_test_2026-10-29', replay_schema_version: 1, engine_build_sha: 'b'.repeat(40),
    config_hash: 'c'.repeat(64), replay_sha256: sha, replay_size_bytes: 10, replay_compressed_size_bytes: 5,
    replay_saved_at_utc: '2026-10-29T08:14:00.000Z', local_path: `replay/${id}.json` });
  await fs.writeFile(path.join(raw, 'raw/replay_index.csv'), m.csv.writeCsv(fields,
    [rawRow('snap_a', 'a'.repeat(64)), rawRow('snap_b', 'd'.repeat(64)), rawRow('snap_z', 'a'.repeat(64))]));
  const join = (await m.val.validateBypass({ dataset: result.directory, raw })).raw_join;
  assert.deepEqual([join.matched, join.matched_valid, join.replay_sha256_mismatch, join.raw_only], [1, 1, ['snap_b'], ['snap_z']]);
  assert.equal(join.bypass_only.length, 6);
  const object = path.join(result.directory, 'objects/snap_a.json.gz');
  await fs.chmod(object, 0o644); await fs.appendFile(object, 'x');
  await assert.rejects(m.val.validateBypass({ dataset: result.directory, raw: null }), /BYPASS_FILE_HASH_MISMATCH/);
  assert.throws(() => m.val.parseArgs(['pkg', '--gt', 'x']), /INVALID_ARGUMENTS/);
});

test('Stored objects must be canonical, bound to their Snapshot and within 512 KB', async () => {
  const m = await api(), f = await fixtures(), row = snapshot('snap_x');
  const store = (payload, text) => gzipSync(Buffer.from(text ?? m.canonicalJson(payload)));
  const good = { ...structuredClone(f.base), snapshot_id: 'snap_x' };
  const ok = m.core.verifyObject(row, store(good));
  assert.equal(ok.payload.snapshot_id, 'snap_x'); assert.equal(ok.contentSha256, m.common.hash(Buffer.from(m.canonicalJson(good))));
  assert.throws(() => m.core.verifyObject(row, store({ ...good, snapshot_id: 'snap_y' })), /BYPASS_SNAPSHOT_ID_MISMATCH/);
  assert.throws(() => m.core.verifyObject(row, store(null, JSON.stringify(good, null, 1))), /BYPASS_NOT_CANONICAL/);
  assert.throws(() => m.core.verifyObject(row, Buffer.from('not gzip')), /BYPASS_GZIP_INVALID/);
  assert.throws(() => m.core.verifyObject(row, gzipSync(Buffer.alloc(600 * 1024, 32))), /BYPASS_TOO_LARGE/);
  assert.throws(() => m.core.verifyObject(row, store({ ...good, extra: 1 })), /BYPASS_SCHEMA_INVALID/);
});

test('Collector report keeps the endpoint bypassStatus and shows it in the Actions summary', async () => {
  const collector = await import('../scripts/pre-sunset-metadata.mjs');
  const report = collector.buildReport({ submit: true, trigger: 'workflow_dispatch', runType: 'scheduled', slot: '1613', slotLocal: '16:13',
    scheduledTimezone: 'Asia/Shanghai', concurrency: 2, cities: ['深圳', '广州'] }, 0, 1000, [
    { requestedCity: '深圳', actualCity: '深圳', score: 60, level: '好', predictionTimeUtc: '2026-10-29T08:13:00Z', status: 'SUBMITTED', bypassStatus: 'SAVED' },
    { requestedCity: '广州', actualCity: '广州', score: 50, level: '好', predictionTimeUtc: '2026-10-29T08:13:00Z', status: 'SUBMITTED', bypassStatus: 'BYPASS_BINDING_MISMATCH' }
  ], {});
  const md = collector.summaryMarkdown(report);
  assert.match(md, /- Bypass: \*\*SAVED=1, BYPASS_BINDING_MISMATCH=1\*\*/);
  assert.match(md, /\| 结果 \| 旁路 \|/); assert.match(md, /\| SUBMITTED \| SAVED \|/);
});
